'use strict'

import InputManager from '../service/input-manager'

const ACTION_LABELS = [
  [InputManager.ACTION_LINK_MOVE_NORTH, 'Up'],
  [InputManager.ACTION_LINK_MOVE_SOUTH, 'Down'],
  [InputManager.ACTION_LINK_MOVE_WEST, 'Left'],
  [InputManager.ACTION_LINK_MOVE_EAST, 'Right'],
  [InputManager.ACTION_LINK_USE_ITEM_A, 'Sword (A)'],
  [InputManager.ACTION_LINK_USE_ITEM_B, 'Item (B)']
]

const CODE_LABELS = {
  ArrowLeft: '←',
  ArrowUp: '↑',
  ArrowRight: '→',
  ArrowDown: '↓',
  Space: 'Space'
}

// Lets the player choose the key of each action: click an action, then press the new key
// (Escape cancels). The choice is kept by InputManager for the next visits
class Controls {
  constructor (container, resetButton, canvas) {
    this.container = container
    this.canvas = canvas
    this.listeningAction = undefined
    this.layoutMap = undefined

    // Name of the keys on the player's keyboard layout (KeyA is "Q" on AZERTY), when the browser tells it
    navigator.keyboard?.getLayoutMap?.().then((layoutMap) => {
      this.layoutMap = layoutMap
      this.render()
    }).catch(() => {})

    resetButton.addEventListener('click', (e) => {
      e.preventDefault()
      this.listeningAction = undefined
      InputManager.resetBindings()
      this.render()
    })

    // Capture phase on window: runs before the game's listeners on document, so the chosen key is not played
    window.addEventListener('keydown', (e) => this.handleKeyDown(e), true)

    this.render()
  }

  getKeyLabel (code) {
    return CODE_LABELS[code] ?? this.layoutMap?.get(code)?.toUpperCase() ?? code.replace(/^(Key|Digit)/, '')
  }

  handleKeyDown (e) {
    if (!this.listeningAction) {
      return
    }
    e.preventDefault()
    e.stopPropagation()
    if (e.code !== 'Escape') {
      InputManager.rebind(this.listeningAction, e.code)
    }
    this.listeningAction = undefined
    this.render()
    this.canvas.focus()
  }

  render () {
    this.container.replaceChildren(...ACTION_LABELS.map(([action, label]) => {
      const row = document.createElement('div')
      row.className = 'form-row'
      const cell = document.createElement('div')
      const labelElement = document.createElement('label')
      labelElement.textContent = label
      const button = document.createElement('button')
      button.type = 'button'
      button.textContent = action === this.listeningAction ? 'Press a key…' : this.getKeyLabel(InputManager.getBinding(action))
      button.addEventListener('click', (e) => {
        e.preventDefault()
        this.listeningAction = action
        this.render()
      })
      cell.append(labelElement, button)
      row.append(cell)

      return row
    }))
  }
}

export { Controls }
